PRAGMA foreign_keys=ON;
CREATE TABLE user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, emailVerified INTEGER NOT NULL DEFAULT 0, image TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE TABLE session (id TEXT PRIMARY KEY, expiresAt INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, ipAddress TEXT, userAgent TEXT, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE);
CREATE INDEX session_user ON session(userId);
CREATE TABLE account (id TEXT PRIMARY KEY, accountId TEXT NOT NULL, providerId TEXT NOT NULL, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, accessToken TEXT, refreshToken TEXT, idToken TEXT, accessTokenExpiresAt INTEGER, refreshTokenExpiresAt INTEGER, scope TEXT, password TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE TABLE verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expiresAt INTEGER NOT NULL, createdAt INTEGER, updatedAt INTEGER);
CREATE TABLE profiles (user_id TEXT PRIMARY KEY REFERENCES user(id) ON DELETE CASCADE, ai_consent INTEGER NOT NULL DEFAULT 0, notifications INTEGER NOT NULL DEFAULT 1);
CREATE TABLE conversations (id TEXT PRIMARY KEY, title TEXT NOT NULL, creator_id TEXT NOT NULL REFERENCES user(id), created_at INTEGER NOT NULL);
CREATE TABLE members (conversation_id TEXT NOT NULL REFERENCES conversations(id), user_id TEXT NOT NULL REFERENCES user(id), joined_at INTEGER NOT NULL, role TEXT NOT NULL DEFAULT 'member', muted INTEGER NOT NULL DEFAULT 0, favorite INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(conversation_id,user_id));
CREATE INDEX member_user ON members(user_id,conversation_id);
CREATE TABLE invites (token TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), creator_id TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE messages (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, conversation_id TEXT NOT NULL REFERENCES conversations(id), author_id TEXT NOT NULL REFERENCES user(id), kind TEXT NOT NULL CHECK(kind IN ('video','audio','photo','text')), text TEXT NOT NULL DEFAULT '', reply_to TEXT, urgent INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL CHECK(state IN ('uploading','ready','live','deleted','failed')), duration_ms INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, transcript TEXT, summary TEXT, ai_status TEXT NOT NULL DEFAULT 'none');
CREATE INDEX message_history ON messages(conversation_id,seq);
CREATE TABLE assets (id TEXT PRIMARY KEY, message_id TEXT NOT NULL REFERENCES messages(id), object_key TEXT NOT NULL UNIQUE, mime TEXT NOT NULL, bytes INTEGER NOT NULL DEFAULT 0, purpose TEXT NOT NULL DEFAULT 'original');
CREATE INDEX asset_message ON assets(message_id);
CREATE TABLE uploads (id TEXT PRIMARY KEY, message_id TEXT NOT NULL REFERENCES messages(id), user_id TEXT NOT NULL, object_key TEXT NOT NULL, upload_id TEXT NOT NULL, mime TEXT NOT NULL, expected_bytes INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'open', created_at INTEGER NOT NULL);
CREATE TABLE upload_parts (upload_id TEXT NOT NULL REFERENCES uploads(id), number INTEGER NOT NULL, etag TEXT NOT NULL, bytes INTEGER NOT NULL, PRIMARY KEY(upload_id,number));
CREATE TABLE reactions (message_id TEXT NOT NULL REFERENCES messages(id), user_id TEXT NOT NULL REFERENCES user(id), emoji TEXT NOT NULL, PRIMARY KEY(message_id,user_id));
CREATE TABLE progress (message_id TEXT NOT NULL REFERENCES messages(id), user_id TEXT NOT NULL REFERENCES user(id), position_ms INTEGER NOT NULL DEFAULT 0, watched INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(message_id,user_id));
CREATE TABLE bookmarks (message_id TEXT NOT NULL REFERENCES messages(id), user_id TEXT NOT NULL REFERENCES user(id), PRIMARY KEY(message_id,user_id));
CREATE TABLE notes (conversation_id TEXT NOT NULL REFERENCES conversations(id), user_id TEXT NOT NULL REFERENCES user(id), text TEXT NOT NULL DEFAULT '', PRIMARY KEY(conversation_id,user_id));
CREATE TABLE reminders (id TEXT PRIMARY KEY, message_id TEXT NOT NULL REFERENCES messages(id), user_id TEXT NOT NULL REFERENCES user(id), due_at INTEGER NOT NULL, sent INTEGER NOT NULL DEFAULT 0);
CREATE TABLE devices (token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES user(id), platform TEXT NOT NULL DEFAULT 'android');
CREATE TABLE blocks (user_id TEXT NOT NULL, blocked_id TEXT NOT NULL, PRIMARY KEY(user_id,blocked_id));
CREATE TABLE reports (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, message_id TEXT NOT NULL, reason TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE outbox (id TEXT PRIMARY KEY, kind TEXT NOT NULL, payload TEXT NOT NULL, created_at INTEGER NOT NULL, delivered_at INTEGER);
CREATE INDEX outbox_pending ON outbox(delivered_at,created_at);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, window INTEGER NOT NULL);
CREATE TABLE live_segments (message_id TEXT NOT NULL REFERENCES messages(id), number INTEGER NOT NULL, object_key TEXT NOT NULL, duration REAL NOT NULL, PRIMARY KEY(message_id,number));
